def _ls(x, y):
    return np.linalg.lstsq(x, y, rcond=None)[0]


def _ones(x):
    return np.column_stack((np.ones(len(x)), x))


def _product_design(w):
    return _ones(w[:, [0, 0, 1, 2]] * w[:, [1, 3, 2, 3]])


def _cosine_design(w):
    return _ones(np.cos(2.4 * w))


def run_node(inputs: dict) -> dict:
    s = inputs['__input__']
    x = np.vstack([s['train']['x'], s['test']['x']])
    u, v = (s['panel_a'][k] for k in ('u', 'v'))
    i, j = np.triu_indices(len(u), 1)
    pars = []
    for k in range(u.shape[1]):
        d = u[i, k] - u[j, k]
        ok = np.abs(d) > 1e-8
        m = np.median((v[i[ok], k] - v[j[ok], k]) / d[ok])
        r = v[:, k] - m * u[:, k]
        r -= np.median(r)
        g = np.abs(r) < max(.001, 6 * np.median(abs(r)))
        pars.append(_ls(_ones(u[g, k:k+1]), v[g, k]))
    off, scale = np.array(pars).T
    z = (x - off) / scale
    b, c = s['panel_b'], s['panel_c']
    product = _product_design(z)
    cosine = _cosine_design(z)
    L = _ones(z) @ _ls(_ones(b['u']), b['v'])
    Q = product @ _ls(_product_design(c['u']), c['v1'])
    R = cosine @ _ls(_cosine_design(c['u']), c['v2'])
    return {'z': z, 'L': L, 'Q': Q, 'R': R, 'product': product[:, 1:], 'cosine': cosine[:, 1:]}
